/**
 * Media and project storage contracts (implementation lands in the engine milestone).
 * Media bytes live in OPFS; projects (JSON) in IndexedDB; a portable project file bundles both.
 */
import type { JobContext } from '../shared/jobs.ts'
import type { Asset, Id, Project } from '../model/types.ts'

export interface MediaStore {
  /** Copies the file into OPFS, probes duration/size/codecs, and returns a new Asset (not yet added to a project). */
  importFile(file: File, ctx?: JobContext): Promise<Asset>
  /** Stores generated bytes (stems, AI images and videos, masks) and returns the Asset. */
  storeBlob(blob: Blob, info: Pick<Asset, 'kind' | 'name' | 'origin'>, ctx?: JobContext): Promise<Asset>
  getFile(asset: Asset): Promise<File>
  remove(asset: Asset): Promise<void>
  usage(): Promise<{ usedBytes: number; quotaBytes: number; persisted: boolean }>
}

export interface ProjectSummary {
  id: Id
  name: string
  updatedAt: string
  thumbnail?: Blob
}

export interface ProjectStore {
  list(): Promise<ProjectSummary[]>
  load(id: Id): Promise<Project>
  save(project: Project): Promise<void>
  remove(id: Id): Promise<void>
  /** Bundles the project JSON and its media into one portable file. */
  exportPortable(project: Project, ctx?: JobContext): Promise<Blob>
  importPortable(file: File, ctx?: JobContext): Promise<Project>
}
